            DefineSection("Scripts", async() => {
                WriteLiteral(@"
    <script>
        function goBack() {
            window.history.back();
        }

        document.addEventListener('DOMContentLoaded', function () {
            const loginForm = document.getElementById('loginForm');
            const passwordToggle = document.getElementById('passwordToggle');
            const passwordInput = document.getElementById('password');
            const loginMessage = document.getElementById('loginMessage');

            // Переключение видимости пароля
            passwordToggle.addEventListener('click', function () {
                const type = passwordInput.getAttribute('type') === 'password' ? 'text' : 'password';
                passwordInput.setAttribute('type', type);
                this.innerHTML = type === 'password' ? '<i class=""fas fa-eye""></i>' : '<i class=""fas fa-eye-slash""></i>';
            });

            // Обработка формы входа
            loginForm.addEventListener('submit', async function (e) {
                e.preventDefault();

                const");
                WriteLiteral(@" formData = {
                    username: document.getElementById('username').value,
                    password: document.getElementById('password').value,
                    rememberMe: document.getElementById('rememberMe').checked
                };

                // Показываем индикатор загрузки
                const submitBtn = loginForm.querySelector('button[type=""submit""]');
                const originalText = submitBtn.innerHTML;
                submitBtn.innerHTML = '<i class=""fas fa-spinner fa-spin me-2""></i>Вход...';
                submitBtn.classList.add('loading');
                submitBtn.disabled = true;

                try {
                    const response = await fetch('/Account/Login', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify(formData)
                    });

                    const result = await response.");
                WriteLiteral(@"json();

                    if (result.success) {
                        loginMessage.innerHTML = `<div class=""alert alert-success"">
                                <i class=""fas fa-check-circle me-2""></i>Успешный вход! Перенаправление...
                            </div>`;

                        setTimeout(() => {
                            window.location.href = result.redirectUrl || '/';
                        }, 1500);
                    } else {
                        loginMessage.innerHTML = `<div class=""alert alert-danger"">
                                <i class=""fas fa-exclamation-triangle me-2""></i>${result.message}
                            </div>`;
                    }
                } catch (error) {
                    console.error('Error:', error);
                    loginMessage.innerHTML = `<div class=""alert alert-danger"">
                            <i class=""fas fa-exclamation-triangle me-2""></i>Произошла ошибка при входе. Попробуйте ещё раз.
                        </div>`;");
                WriteLiteral(@"
                } finally {
                    // Восстанавливаем кнопку
                    submitBtn.innerHTML = originalText;
                    submitBtn.classList.remove('loading');
                    submitBtn.disabled = false;
                }
            });

            // Закрытие по ESC
            document.addEventListener('keydown', function (e) {
                if (e.key === 'Escape') {
                    goBack();
                }
            });

            // Закрытие по клику вне модального окна
            document.querySelector('.login-modal-overlay').addEventListener('click', function (e) {
                if (e.target === this) {
                    goBack();
                }
            });
        });
    </script>
");
            }
            );
